css:
.reefcoast-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #143642;
    background: linear-gradient(165deg, #fbf6ec 0%, #eef6f4 55%, #e2f1ef 100%);
    border-radius: 18px;
}

.reefcoast-container * {
    box-sizing: border-box;
}

.reefcoast-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0a4f5c 0%, #0f8a8f 52%, #f2a541 130%);
    color: #f1fbf9;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(10, 79, 92, 0.30);
}

.reefcoast-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.reefcoast-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffe2b0;
    background: rgba(255, 226, 176, 0.14);
    border: 1px solid rgba(255, 226, 176, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.reefcoast-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d8f1ed;
}

.reefcoast-region {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.reefcoast-region-item {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(20, 54, 66, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.reefcoast-region-assets { border-left: 5px solid #0f8a8f; }
.reefcoast-region-constraints { border-left: 5px solid #d9742a; }

.reefcoast-region-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #0a4f5c;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.reefcoast-region-assets .reefcoast-region-name { color: #0c7a7f; }
.reefcoast-region-constraints .reefcoast-region-name { color: #c0631f; }

.reefcoast-region-meta {
    font-size: 0.82rem;
    color: #587179;
    line-height: 1.4;
}

.reefcoast-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3f5961;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.reefcoast-period-counter #currentDay,
.reefcoast-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f8a8f;
}

.reefcoast-round-name {
    background: rgba(15, 138, 143, 0.14);
    color: #0c7378;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.reefcoast-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b5631c;
    background: rgba(217, 116, 42, 0.14);
    border: 1px solid rgba(217, 116, 42, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.reefcoast-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.reefcoast-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(20, 54, 66, 0.08);
    border-top: 4px solid #0f8a8f;
}

.reefcoast-card-ventures { border-top-color: #0f8a8f; }
.reefcoast-card-jobs { border-top-color: #2f8f4e; }
.reefcoast-card-leverage { border-top-color: #d9742a; }
.reefcoast-card-engagement { border-top-color: #5b6fc0; }

.reefcoast-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #687f86;
}

.reefcoast-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0a4f5c;
    font-variant-numeric: tabular-nums;
}

.reefcoast-card-ventures .reefcoast-value { color: #0c7a7f; }
.reefcoast-card-jobs .reefcoast-value { color: #2f8f4e; }
.reefcoast-card-leverage .reefcoast-value { color: #c0631f; }
.reefcoast-card-engagement .reefcoast-value { color: #5b6fc0; }

.reefcoast-sublabel {
    font-size: 0.75rem;
    color: #7a9098;
    line-height: 1.35;
}

.reefcoast-card-leverage.reefcoast-lev-danger { border-top-color: #d64545; }
.reefcoast-card-leverage.reefcoast-lev-danger .reefcoast-value { color: #d64545; }
.reefcoast-card-leverage.reefcoast-lev-good { border-top-color: #2f8f4e; }
.reefcoast-card-leverage.reefcoast-lev-good .reefcoast-value { color: #2f8f4e; }

.reefcoast-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e0eae8;
    color: #3f5961;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.reefcoast-budget-bar #riskDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #d64545;
    font-weight: 800;
}

.reefcoast-budget-bar.reefcoast-risk-low #riskDisplay { color: #2f8f4e; }
.reefcoast-budget-bar.reefcoast-risk-mid #riskDisplay { color: #c0631f; }

.reefcoast-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #0f8a8f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 54, 66, 0.07);
}

.reefcoast-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.reefcoast-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0a4f5c;
    margin-bottom: 6px;
}

.reefcoast-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2f4750;
}

.reefcoast-briefing-text strong { color: #0c7a7f; }
.reefcoast-briefing-text em { color: #c0631f; font-style: italic; }

.reefcoast-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 54, 66, 0.07);
}

.reefcoast-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0a4f5c;
    border-bottom: 2px solid #e6efed;
    padding-bottom: 8px;
}

.reefcoast-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #294149;
    margin: 14px 0 6px;
}

.reefcoast-container select,
.reefcoast-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d6d4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #143642;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.reefcoast-container select:focus,
.reefcoast-container input[type="number"]:focus {
    outline: none;
    border-color: #0f8a8f;
    box-shadow: 0 0 0 3px rgba(15, 138, 143, 0.16);
}

.reefcoast-container select option {
    background-color: #ffffff;
    color: #143642;
}

.reefcoast-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0f8a8f;
}

.reefcoast-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #3f5961;
    margin-top: 4px;
}

.reefcoast-range-readout span:nth-child(2) {
    color: #0f8a8f;
    font-weight: 800;
}

.reefcoast-hint {
    font-size: 0.8rem;
    color: #7a9098;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.reefcoast-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.reefcoast-container .btn-primary {
    background: linear-gradient(135deg, #0c7a7f 0%, #0f8a8f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(12, 122, 127, 0.32);
}

.reefcoast-container .btn-primary:hover {
    filter: brightness(1.07);
}

.reefcoast-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d6d4;
    color: #587179;
    background: transparent;
}

.reefcoast-coach {
    background: linear-gradient(160deg, #0a4f5c 0%, #0c5d68 100%);
    color: #e1f3f0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(10, 79, 92, 0.24);
}

.reefcoast-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffe2b0;
    margin-bottom: 8px;
}

.reefcoast-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.reefcoast-coach-body strong { color: #6fe0d4; }
.reefcoast-coach-body em { color: #ffd9a0; font-style: italic; }

.reefcoast-history,
.reefcoast-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 54, 66, 0.07);
}

.reefcoast-history h3,
.reefcoast-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0a4f5c;
}

.reefcoast-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2f4750;
}

.reefcoast-container table#usfHistoryTable th {
    background: #ecf5f3;
    color: #0c7a7f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e6e3;
}

.reefcoast-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef3f2;
    color: #2f4750;
}

.reefcoast-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf9;
}

.reefcoast-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .reefcoast-container {
        padding: 14px;
    }
    .reefcoast-header h1 {
        font-size: 1.7rem;
    }
    .reefcoast-region {
        flex-direction: column;
    }
    .reefcoast-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .reefcoast-value {
        font-size: 2rem;
    }
    .reefcoast-clock {
        margin-left: 0;
    }
    .reefcoast-period-counter {
        font-size: 0.88rem;
    }
    .reefcoast-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .reefcoast-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (pbv- prefix; regional-green theme) ---- */
.pbv-completion { padding: 8px 4px 4px; }
.pbv-cm-head { text-align: center; margin-bottom: 16px; }
.pbv-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a54; }
.pbv-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6b8a7a; }
.pbv-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #14302a; }
.pbv-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.pbv-cm-yes { background: rgba(31,122,84,0.14); color: #1f7a54; border: 1px solid rgba(31,122,84,0.45); }
.pbv-cm-mid { background: rgba(196,142,47,0.13); color: #b3801f; border: 1px solid rgba(196,142,47,0.40); }
.pbv-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.pbv-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.pbv-cm-metric { flex: 1 1 100px; min-width: 92px; background: rgba(31,122,84,0.07); border: 1px solid rgba(31,122,84,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.pbv-cm-mv { display: block; font-size: 1.2rem; font-weight: 800; color: #1f7a54; }
.pbv-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #6b8a7a; text-transform: uppercase; letter-spacing: 0.03em; }
.pbv-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14302a; }
.pbv-cm-insights { margin: 0; padding-left: 20px; }
.pbv-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3a4f47; }

