(function() {
    'use strict';

    class PlaceBasedVentureAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Place-Based Venture`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Reef Coast Futures).
            this.BUDGET = 8.0;            // A$8M annual program budget
            this.CONTINGENT = 3.2;       // A$3.2M (40%) performance-contingent
            this.JOBS_LOST = 600;        // direct jobs from the anchor wind-down
            this.PIPELINE = 10;          // 10 ventures in the pipeline
            this.START_LEVERAGE = 0.4;   // current funding leverage
            this.TARGET_LEVERAGE = 1.5;  // state target
            this.START_ENGAGE = 40;      // baseline ecosystem-engagement score
            this.SURVIVAL_BENCH = 55;    // national regional survival benchmark (%)
            this.START_SURVIVAL = 42;    // regional 3-yr survival (%)

            // Concept truths (the place-based answers).
            this.TRUE_DIAGNOSIS = `placefit`;
            this.TRUE_PROGRAM = `sector`;
            this.TRUE_PARTNER = `leverage`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ventures: 0,                 // ventures activated (resilient, scaling)
                    jobs: 0,                     // new private-sector jobs created
                    leverage: this.START_LEVERAGE,
                    engagement: this.START_ENGAGE,
                    survival: this.START_SURVIVAL,
                    // Sticky run-defining penalty flags (set when an error is committed).
                    importedModel: false,        // generic metropolitan accelerator
                    thinSpread: false,           // budget spread thinly across all ventures
                    fundedDecline: false,        // propped up the departing anchor employer
                    trophyPartners: false,       // treated all partners as equal / photo
                    ignoredInclusion: false,     // routed only through established community
                    placeRead: false,           // correctly diagnosed the place in Round 1
                    spentDiscretionary: 0,       // A$M of discretionary budget committed
                    venturesHistory: [0],
                    jobsHistory: [0],
                    leverageHistory: [this.START_LEVERAGE],
                    engagementHistory: [this.START_ENGAGE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the five classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    diagnosis: `copy`,
                    failure: `underfunded`,
                    inclusion: `established`,
                    focus: 5,
                    alloc: `spread`,
                    anchor: `prop`,
                    placefit: `ignore`,
                    depth: 120,
                    program: `accelerator`,
                    partner: `even`,
                    indigenous: `no`,
                    coinvest: `0`,
                    doubledown: `optics`,
                    pitch: `grants`,
                    additionality: `dodge`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const di = document.getElementById(`diagnosisInput`);
                const fa = document.getElementById(`failureInput`);
                const inc = document.getElementById(`inclusionInput`);
                const fo = document.getElementById(`focusInput`);
                if (di) decisions.diagnosis = di.value;
                if (fa) decisions.failure = fa.value;
                if (inc) decisions.inclusion = inc.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 1 || decisions.focus > 6) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const al = document.getElementById(`allocInput`);
                const an = document.getElementById(`anchorInput`);
                const pf = document.getElementById(`placefitInput`);
                const de = document.getElementById(`depthInput`);
                if (al) decisions.alloc = al.value;
                if (an) decisions.anchor = an.value;
                if (pf) decisions.placefit = pf.value;
                if (de) decisions.depth = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 80 || decisions.depth > 600) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`programInput`);
                const pa = document.getElementById(`partnerInput`);
                const ind = document.getElementById(`indigenousInput`);
                const co = document.getElementById(`coinvestInput`);
                if (pr) decisions.program = pr.value;
                if (pa) decisions.partner = pa.value;
                if (ind) decisions.indigenous = ind.value;
                if (co) decisions.coinvest = co.value;
                if (!Number.isFinite(parseFloat(decisions.coinvest)) || parseFloat(decisions.coinvest) < 0) {
                    warn(`warn_coinvest_value`); return false;
                }
            } else if (round === 4) {
                const dd = document.getElementById(`doubledownInput`);
                const pi = document.getElementById(`pitchInput`);
                const ad = document.getElementById(`additionalityInput`);
                const cv = document.getElementById(`convictionInput`);
                if (dd) decisions.doubledown = dd.value;
                if (pi) decisions.pitch = pi.value;
                if (ad) decisions.additionality = ad.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let venturesDelta = 0, jobsDelta = 0, leverageDelta = 0, engagementDelta = 0, survivalDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the place (Common Error 1: imported playbook; Error 5: inclusion).
                switch (d.diagnosis) {
                    case `placefit`: ds.placeRead = true; engagementDelta += 8; survivalDelta += 3; coachKey = `coach_r1_placefit`; break;
                    case `legacy`: engagementDelta += 2; survivalDelta -= 2; coachKey = `coach_r1_legacy`; break;
                    case `copy`: ds.importedModel = true; engagementDelta -= 4; survivalDelta -= 3; coachKey = `coach_r1_copy`; break;
                }

                switch (d.failure) {
                    case `context`: engagementDelta += 5; if (d.diagnosis === `placefit`) coachKey = `coach_r1_sharp`; break;
                    case `underfunded`: ds.importedModel = true; engagementDelta -= 3; coachKey = `coach_r1_underfunded`; break;
                    case `founders`: engagementDelta -= 4; coachKey = `coach_r1_founders`; break;
                }

                switch (d.inclusion) {
                    case `broad`: engagementDelta += 6; leverageDelta += 0.05; break;
                    case `established`: ds.ignoredInclusion = true; engagementDelta -= 3; coachKey = `coach_r1_established`; break;
                    case `ignore`: ds.ignoredInclusion = true; engagementDelta -= 6; coachKey = `coach_r1_ignoreincl`; break;
                }

                // Focus: a sharp 2–3 sectors beats trying to serve everything.
                if (d.focus <= 3) { engagementDelta += 4; survivalDelta += 2; }
                else if (d.focus >= 5) { engagementDelta -= 3; survivalDelta -= 2; }

                summaryKey = (d.diagnosis === `placefit` && d.failure === `context` && d.inclusion === `broad`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate across the pipeline (Common Error 2: thin spread; Error 3: funding decline).
                const depthFactor = Math.max(0, Math.min(1, (d.depth - 80) / (600 - 80))); // 0..1
                ds.spentDiscretionary = Math.round((ds.spentDiscretionary + 4.8) * 10) / 10;

                switch (d.alloc) {
                    case `concentrate`:
                        venturesDelta += 3; jobsDelta += 130; survivalDelta += 6; coachKey = `coach_r2_concentrate`;
                        break;
                    case `hedge`:
                        venturesDelta += 2; jobsDelta += 70; survivalDelta += 1; coachKey = `coach_r2_hedge`;
                        break;
                    case `spread`:
                        ds.thinSpread = true;
                        venturesDelta += 1; jobsDelta += 30; survivalDelta -= 5; coachKey = `coach_r2_spread`;
                        break;
                }

                // Depth multiplies whatever the allocation strategy produced.
                venturesDelta = Math.round(venturesDelta * (0.5 + depthFactor));
                jobsDelta = Math.round(jobsDelta * (0.5 + depthFactor));
                if (d.depth <= 120 && d.alloc !== `concentrate`) { survivalDelta -= 3; }

                switch (d.anchor) {
                    case `transition`: jobsDelta += 60; engagementDelta += 5; survivalDelta += 2; break;
                    case `prop`: ds.fundedDecline = true; jobsDelta += 90; survivalDelta -= 4; coachKey = `coach_r2_prop`; break;
                    case `ignore`: engagementDelta -= 4; coachKey = `coach_r2_ignoreanchor`; break;
                }

                switch (d.placefit) {
                    case `strong`: venturesDelta += 2; survivalDelta += 5; leverageDelta += 0.1; if (d.alloc === `concentrate`) coachKey = `coach_r2_placefit`; break;
                    case `some`: survivalDelta += 1; break;
                    case `ignore`: survivalDelta -= 3; engagementDelta -= 2; break;
                }

                summaryKey = (d.alloc === `concentrate` && d.anchor === `transition`) ? `sum_r2_good` :
                             (d.alloc === `spread` ? `sum_r2_spread` :
                             (d.anchor === `prop` ? `sum_r2_decline` : `sum_r2_weak`));
            } else if (round === 3) {
                // Program model + partner prioritisation (Errors 1, 4, 5; leverage spine).
                switch (d.program) {
                    case `sector`: venturesDelta += 3; survivalDelta += 5; engagementDelta += 4; break;
                    case `accelerator`: ds.importedModel = true; venturesDelta -= 1; survivalDelta -= 4; engagementDelta -= 2; coachKey = `coach_r3_accelerator`; break;
                    case `grants`: venturesDelta -= 1; survivalDelta -= 3; engagementDelta -= 4; coachKey = `coach_r3_grants`; break;
                }

                // Partner prioritisation is THE leverage lever.
                switch (d.partner) {
                    case `leverage`: engagementDelta += 8; coachKey = `coach_r3_leverage`; break;
                    case `even`: ds.trophyPartners = true; engagementDelta -= 2; coachKey = `coach_r3_even`; break;
                    case `goodwill`: ds.trophyPartners = true; engagementDelta -= 4; coachKey = `coach_r3_goodwill`; break;
                }

                switch (d.indigenous) {
                    case `yes`: engagementDelta += 7; leverageDelta += 0.1; jobsDelta += 40; break;
                    case `token`: ds.ignoredInclusion = true; engagementDelta += 1; break;
                    case `no`: ds.ignoredInclusion = true; engagementDelta -= 5; coachKey = `coach_r3_noindigenous`; break;
                }

                // Co-investment commitment directly drives leverage toward the 1.5x target.
                const co = parseFloat(d.coinvest);
                if (co >= 1.4) { leverageDelta += 0.65; engagementDelta += 4; }
                else if (co >= 0.6) { leverageDelta += 0.25; }
                else { leverageDelta -= 0.05; if (coachKey === `coach_default`) coachKey = `coach_r3_nocoinvest`; }

                // Trophy partners CAP the leverage gain — partners aren't trophies.
                if (ds.trophyPartners) { leverageDelta = Math.min(leverageDelta, 0.15); }

                summaryKey = (d.program === `sector` && d.partner === `leverage` && co >= 1.4) ? `sum_r3_good` :
                             (d.program === `accelerator` ? `sum_r3_imported` :
                             (d.partner !== `leverage` ? `sum_r3_trophy` : `sum_r3_weak`));
            } else if (round === 4) {
                // Deliver outcomes and make the case to the state (Errors 2 & 3 reprised).
                switch (d.doubledown) {
                    case `winners`: venturesDelta += 2; jobsDelta += 80; leverageDelta += 0.2; survivalDelta += 4; coachKey = `coach_r4_winners`; break;
                    case `optics`: ds.thinSpread = true; venturesDelta += 0; jobsDelta += 20; survivalDelta -= 3; coachKey = `coach_r4_optics`; break;
                    case `decline`: ds.fundedDecline = true; jobsDelta += 50; survivalDelta -= 4; coachKey = `coach_r4_decline`; break;
                }

                switch (d.pitch) {
                    case `outcomes`: engagementDelta += 8; leverageDelta += 0.1; if (d.doubledown === `winners`) coachKey = `coach_r4_outcomes`; break;
                    case `grants`: engagementDelta -= 4; coachKey = `coach_r4_grants`; break;
                    case `spin`: engagementDelta -= 6; coachKey = `coach_r4_spin`; break;
                }

                switch (d.additionality) {
                    case `own`: engagementDelta += 6; leverageDelta += 0.05; break;
                    case `dodge`: engagementDelta -= 4; coachKey = `coach_r4_dodge`; break;
                    case `deny`: engagementDelta -= 6; coachKey = `coach_r4_deny`; break;
                }

                if (d.conviction >= 60) { engagementDelta += 3; }
                else if (d.conviction <= 25) { engagementDelta -= 3; }

                summaryKey = (d.doubledown === `winners` && d.pitch === `outcomes` && d.additionality === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.ventures = Math.max(0, Math.min(this.PIPELINE, ds.ventures + venturesDelta));
            ds.jobs = Math.max(0, Math.round(ds.jobs + jobsDelta));
            ds.leverage = Math.max(0, Math.round((ds.leverage + leverageDelta) * 100) / 100);
            ds.engagement = Math.max(0, Math.min(100, Math.round(ds.engagement + engagementDelta)));
            ds.survival = Math.max(0, Math.min(100, Math.round((ds.survival + survivalDelta) * 10) / 10));

            // ---- Sticky penalty flags CAP the KPIs (not soft deltas a later round washes out). ----
            // Thin spread repeats the accelerator failure: many starts, few survivors.
            if (ds.thinSpread) {
                ds.ventures = Math.min(ds.ventures, 4);
                ds.survival = Math.min(ds.survival, 46);
            }
            // Imported metropolitan model: caps activated ventures and survival.
            if (ds.importedModel) {
                ds.ventures = Math.min(ds.ventures, 5);
                ds.survival = Math.min(ds.survival, 49);
            }
            // Funding the decline: jobs are temporary, not new resilient enterprise.
            if (ds.fundedDecline) {
                ds.ventures = Math.min(ds.ventures, 5);
            }
            // Trophy partners / ignored inclusion: leverage and engagement stay capped.
            if (ds.trophyPartners) {
                ds.leverage = Math.min(ds.leverage, 0.8);
                ds.engagement = Math.min(ds.engagement, 62);
            }
            if (ds.ignoredInclusion) {
                ds.engagement = Math.min(ds.engagement, 70);
            }

            ds.venturesHistory.push(ds.ventures);
            ds.jobsHistory.push(ds.jobs);
            ds.leverageHistory.push(ds.leverage);
            ds.engagementHistory.push(ds.engagement);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite score + grade letter to the reporting/grading layer every
            // period (express/results_utils.php::express_resolveDomainScore reads
            // domainState.performance.overallScore; express_extractHistory reads it per period).
            // Scoring UNCHANGED - _composite() reuses the exact v1.0.0 formula.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                ventures: ds.ventures,
                venturesDelta: venturesDelta,
                jobs: ds.jobs,
                jobsDelta: Math.round(jobsDelta),
                leverage: ds.leverage,
                leverageDelta: Math.round(leverageDelta * 100) / 100,
                engagement: ds.engagement,
                survival: ds.survival,
                importedModel: ds.importedModel,
                thinSpread: ds.thinSpread,
                fundedDecline: ds.fundedDecline,
                trophyPartners: ds.trophyPartners,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _riskLabel(leverage, engagement) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (leverage >= 1.5 && engagement >= 70) return t(`risk_low`);
            if (leverage >= 0.9 || engagement >= 60) return t(`risk_mid`);
            return t(`risk_high`);
        }

        _fmtLeverage(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `x`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`venturesDisplay`, `domainState.ventures`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`jobsDisplay`, `domainState.jobs`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`leverageDisplay`, `domainState.leverage`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.reefcoast-card-leverage`);
                if (card) {
                    card.classList.toggle(`reefcoast-lev-danger`, n < 0.9);
                    card.classList.toggle(`reefcoast-lev-good`, n >= self.TARGET_LEVERAGE);
                }
                return self._fmtLeverage(n);
            });

            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`riskDisplay`, `domainState.leverage`, (v) => {
                const lev = Number(v);
                const eng = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) ? window.mySimulation.state.domainState.engagement : 0;
                const bar = document.querySelector(`.reefcoast-budget-bar`);
                if (bar) {
                    const low = lev >= 1.5 && eng >= 70;
                    const mid = !low && (lev >= 0.9 || eng >= 60);
                    bar.classList.toggle(`reefcoast-risk-low`, low);
                    bar.classList.toggle(`reefcoast-risk-mid`, mid);
                }
                return self._riskLabel(lev, eng);
            });

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Depth slider readout.
            const de = document.getElementById(`depthInput`);
            const deReadout = document.getElementById(`depthReadout`);
            if (de && deReadout) {
                deReadout.textContent = de.value;
                de.addEventListener(`input`, function() { deReadout.textContent = de.value; });
            }
        }

