                                data: [],
                                borderColor: `#d9742a`,
                                backgroundColor: `rgba(217,116,42,0.10)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#d9742a`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_engagement`, `Ecosystem engagement (0–100)`),
                                data: [],
                                borderColor: `#5b6fc0`,
