        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.venturesHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Index everything onto a shared 0–100 axis.
            const venturesScaled = ds.venturesHistory.map((v) => Math.round(v * 10));        // 10 ventures -> 100
            const leverageScaled = ds.leverageHistory.map((v) => Math.min(100, Math.round(v * 40))); // 1.5x -> 60, 2.5x -> 100
            const jobsScaled = ds.jobsHistory.map((v) => Math.min(100, Math.round(v / 10)));  // 1000 jobs -> 100
            return {
                reefCoastChart: {
                    labels: labels,
                    datasets: [
                        { data: venturesScaled },
                        { data: leverageScaled },
                        { data: ds.engagementHistory.map((v) => Math.round(v)) },
                        { data: jobsScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // 0-100 composite - IDENTICAL formula to v1.0.0 getPerformanceSummary.
            const ventures = Math.round(ds.ventures);
            const jobs = Math.round(ds.jobs);
            const leverage = Math.round(ds.leverage * 100) / 100;
            const engagement = Math.round(ds.engagement);
            const venturesScore = (ventures / this.PIPELINE) * 100;
            const jobsScore = Math.min(100, (jobs / 350) * 100);
            const leverageScore = Math.min(100, (leverage / this.TARGET_LEVERAGE) * 100);
            return Math.round(venturesScore * 0.26 + jobsScore * 0.24 + leverageScore * 0.28 + engagement * 0.22);
        }

        _verdictKey(ds, composite) {
            // Verdict tier -> i18n key. Thresholds IDENTICAL to v1.0.0 (labels now localized).
            const ventures = Math.round(ds.ventures);
            const jobs = Math.round(ds.jobs);
            const leverage = Math.round(ds.leverage * 100) / 100;
            const engagement = Math.round(ds.engagement);
            const hitLeverage = leverage >= this.TARGET_LEVERAGE;
            const hitVentures = ventures >= 6;
            const hitJobs = jobs >= 300;
            const strongEngage = engagement >= 70;
            const anyError = ds.importedModel || ds.thinSpread || ds.fundedDecline || ds.trophyPartners || ds.ignoredInclusion;
            if (!anyError && hitLeverage && hitVentures && hitJobs && strongEngage && composite >= 75) return `verdict_renewal`;
            if (!ds.thinSpread && !ds.importedModel && hitLeverage && (hitVentures || hitJobs)) return `verdict_targets`;
            if (ds.thinSpread) return `verdict_thinspread`;
            if (ds.importedModel) return `verdict_imported`;
            if (ds.fundedDecline && !hitVentures) return `verdict_decline`;
            if (ds.trophyPartners && !hitLeverage) return `verdict_stalled`;
            if (composite >= 55) return `verdict_partial`;
            return `verdict_forfeited`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const ventures = Math.round(ds.ventures);
            const jobs = Math.round(ds.jobs);
            const leverage = Math.round(ds.leverage * 100) / 100;
            const engagement = Math.round(ds.engagement);
            const survival = Math.round(ds.survival * 10) / 10;

            // v1.1.0: composite via shared helper so per-period persisted score == completion score.
            const composite = this._composite(ds);

            const hitLeverage = leverage >= this.TARGET_LEVERAGE;
            const hitVentures = ventures >= 6;
            const hitJobs = jobs >= 300;
            const strongEngage = engagement >= 70;
            const anyError = ds.importedModel || ds.thinSpread || ds.fundedDecline || ds.trophyPartners || ds.ignoredInclusion;

            // Pattern detection (the dominant error narrative).
            let pattern = `mixed`;
            if (ds.importedModel) pattern = `imported`;
            else if (ds.thinSpread) pattern = `spread`;
            else if (ds.fundedDecline) pattern = `decline`;
            else if (ds.trophyPartners) pattern = `trophy`;
            else if (ds.ignoredInclusion) pattern = `inclusion`;
            else if (hitLeverage && hitVentures && hitJobs && strongEngage) pattern = `placebased`;

            // The headline anti-pattern must NOT reach the TOP verdict — GATE it.
            // v1.1.0: verdict tier -> localized label via shared helper (thresholds unchanged).
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (pattern === `placebased`) insights.push(window.mySimulation.t(`insight_placebased`));
            else if (pattern === `imported`) insights.push(window.mySimulation.t(`insight_imported`));
            else if (pattern === `spread`) insights.push(window.mySimulation.t(`insight_spread`));
            else if (pattern === `decline`) insights.push(window.mySimulation.t(`insight_decline`));
            else if (pattern === `trophy`) insights.push(window.mySimulation.t(`insight_trophy`));
            else if (pattern === `inclusion`) insights.push(window.mySimulation.t(`insight_inclusion`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!hitLeverage) insights.push(window.mySimulation.t(`insight_leverage_low`));
            if (ds.fundedDecline) insights.push(window.mySimulation.t(`insight_decline_cost`));
            if (ds.ignoredInclusion && pattern !== `inclusion`) insights.push(window.mySimulation.t(`insight_inclusion_cost`));
            if (survival < this.SURVIVAL_BENCH && !hitVentures) insights.push(window.mySimulation.t(`insight_survival_low`));
            if (!anyError && hitLeverage && hitVentures && hitJobs && strongEngage) insights.push(window.mySimulation.t(`insight_caused`));

            return {
                ventures: ventures,
                jobs: jobs,
                leverage: leverage,
                engagement: engagement,
                survival: survival,
                hitLeverage: hitLeverage,
                hitVentures: hitVentures,
                hitJobs: hitJobs,
                strongEngage: strongEngage,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const ventures = Math.round(Number(s.ventures || 0));
            const jobs = Math.round(Number(s.jobs || 0));
            const leverage = this._fmtLeverage(Number(s.leverage || 0));
            const engagement = Math.round(Number(s.engagement || 0));
            const survival = Math.round(Number(s.survival || 0)) + '%';
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const renewed = s.verdictKey === 'verdict_renewal';
            const badgeCls = renewed ? 'pbv-cm-yes' : (score >= 62 ? 'pbv-cm-mid' : 'pbv-cm-no');
            const metric = (val, lab) => '<div class="pbv-cm-metric"><span class="pbv-cm-mv">' + val + '</span><span class="pbv-cm-ml">' + lab + '</span></div>';
            const metrics = metric(ventures, T('cm_m_ventures'))
                + metric(jobs, T('cm_m_jobs'))
                + metric(leverage, T('cm_m_leverage'))
                + metric(engagement, T('cm_m_engagement'))
                + metric(survival, T('cm_m_survival'));
            return ''
                + '<div class="pbv-completion">'
                +   '<div class="pbv-cm-head">'
                +     '<div class="pbv-cm-score">' + score + '<span class="pbv-cm-score-max">/100</span></div>'
                +     '<div class="pbv-cm-grade">' + verdict + ' <span class="pbv-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="pbv-cm-metrics">' + metrics + '</div>'
                +   '<div class="pbv-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="pbv-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.thinSpread) return window.mySimulation.t(`hint_spread`);
            if (ds.importedModel) return window.mySimulation.t(`hint_imported`);
            if (ds.fundedDecline) return window.mySimulation.t(`hint_decline`);
            if (ds.trophyPartners && ds.leverage < 0.9) return window.mySimulation.t(`hint_trophy`);
            if (ds.leverage < 0.9 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_leverage`);
            if (ds.ventures >= 6 && ds.leverage >= 1.5 && ds.engagement >= 70) return window.mySimulation.t(`hint_strong`);
            return null;
        }

