                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.ventures`, label: `Ventures`, i18nKey: `col_ventures`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.jobs`, label: `Jobs`, i18nKey: `col_jobs`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.leverage`, label: `Leverage`, i18nKey: `col_leverage`, formatter: (v) => `${Number(v).toFixed(1)}x` },
                { key: `results.engagement`, label: `Engagement`, i18nKey: `col_engagement`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

