        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Place-Based Venture`,
                    subtitle:               `You are the new CEO of a regional development agency on an A$8M budget. The region’s biggest employer is winding down 600 jobs, and the state has made A$3.2M of next year’s funding contingent on real outcomes in 12 months. Stop copying capital-city accelerators. Read this place, back the right ventures, fund the partners who actually bring co-investment — and hit the state’s targets.`,
                    header_tag:             `21 January 2026 · Reef Coast Futures · Townsville, North Queensland`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
                    submit_btn:             `Commit the Decision`,
                    undo_btn:               `Undo Last Round`,
                    history_heading:        `Round-by-Round Record`,
                    chart_heading:          `Ventures, Jobs, Leverage & Engagement Trajectory`,
                    chart_start:            `Baseline`,
                    coach_header:           `Facilitator (the state funder & the RCF board)`,
                    coach_intro:            `Twelve months, three targets: ventures activated, jobs created, and funding leverage from 0.4x toward 1.5x — with A$3.2M riding on it and a rival region in line for the larger allocation. The region starts many ventures and scales almost none. Spread the money thinly to look fair and you’ll repeat the accelerator that produced 3 survivors from A$1.5M. Read this place first, concentrate on place-fit ventures, and back the partners that actually bring private capital.`,

                    region_assets:          `Distinctive assets`,
                    region_assets_meta:     `Marine science · renewable-energy potential · agtech adjacent to sugar`,
                    region_constraints:     `Constraints`,
                    region_constraints_meta:`Thin capital · distance to markets · narrow talent pool · 42% survival vs 55%`,

                    ventures_label:         `Ventures Activated`,
                    ventures_sub:           `Resilient enterprises actually scaling · state counts these, not grants handed out`,
                    jobs_label:             `Jobs Created`,
                    jobs_sub:               `New private-sector jobs · against 600 direct + ~900 indirect lost`,
                    leverage_label:         `Funding Leverage`,
                    leverage_sub:           `Private A$ pulled in per A$1 of RCF · now 0.4x · state target 1.5x`,
                    engagement_label:       `Ecosystem Engagement`,
                    engagement_sub:         `Health of partner connections (0–100) · the orchestration, not just grant-giving`,
                    budget_label:           `Contingent funding at stake · A$3.2M on outcomes · 12-month review`,
                    risk_high:              `At Risk`,
                    risk_mid:               `Improving`,
                    risk_low:               `On Track`,

                    clock_r1:               `Month 0 · read the place`,
                    clock_r2:               `Months 1–4 · allocate the pipeline`,
                    clock_r3:               `Months 4–8 · program & partners`,
                    clock_r4:               `Month 12 · the state review`,

                    round_name_r1:          `Read the Place`,
                    round_name_r2:          `Allocate Support`,
                    round_name_r3:          `Program & Partners`,
                    round_name_r4:          `Make the Case`,

                    briefing_title_r1:      `Round 1 — Read the place`,
                    briefing_text_r1:       `It is day one of your place-based mandate. Reef Coast Futures runs on <strong>A$8M</strong> for a region of 230,000 that starts many ventures but scales few — <strong>42% three-year survival versus a 55% benchmark</strong>. A prior <strong>A$1.5M generic accelerator produced just 3 survivors in two years</strong>. Applying Barrett’s place-based view, diagnose what is genuinely distinctive here — its <em>assets</em> (marine science, renewables, agtech adjacent to sugar), its <em>constraints</em> (thin capital, distance to markets, narrow talent), and <em>why an imported metropolitan model failed</em>. Read the place before you design anything.`,
                    briefing_title_r2:      `Round 2 — Allocate support across the pipeline`,
                    briefing_text_r2:       `Allocate the <strong>A$4.8M discretionary budget</strong> across the 10-venture pipeline. The core tension is <strong>concentration vs spread</strong>: back a few high-place-fit, high-jobs ventures deeply, or hedge thinly across all ten to look fair. Spreading thin is politically easy and historically the accelerator failure — many starts, few survivors. Decide how to handle the <em>600 disappearing anchor jobs</em>: prop up a managed decline, or fund transition into <em>new</em> enterprise. Weight place-fit, and fund deep enough that ventures actually scale.`,
                    briefing_title_r3:      `Round 3 — Choose the program, prioritise partners`,
                    briefing_text_r3:       `Design the <em>how</em>. Choose a development-program model fitted to place — a sector incubator (marine/renewables), founder small-business skills, market access — versus re-running the generic accelerator. Then <strong>prioritise ecosystem partners under limited funding</strong>: the right partners bring <em>co-investment</em>, not just goodwill, and partner choice is the primary lever to move leverage from <strong>0.4x toward the 1.5x target</strong>. Fund a genuine community-enterprise and Indigenous-business stream — place-based means socially inclusive, and the state weighs inclusive outcomes.`,
                    briefing_title_r4:      `Round 4 — Deliver outcomes, make the case`,
                    briefing_text_r4:       `Twelve-month outcomes are back. Decide what to <strong>double down on and what to cut</strong>, then present to the state funder a place-based recovery strategy that secures the contingent <strong>A$3.2M</strong> and the larger future allocation. Lead with <em>outcomes and additionality</em> — ventures activated, jobs created, leverage toward 1.5x, engagement — each genuinely <em>caused</em> by the intervention, not what would have happened anyway. A rival region is in line if you miss.`,

                    r1_diagnosis_label:     `What is genuinely distinctive about this region — and where can context-fit support build resilient enterprise?`,
                    r1_failure_label:       `Why did the previous A$1.5M generic accelerator produce just 3 survivors in two years?`,
                    r1_inclusion_label:     `Whose ventures and talent does a place-based read of this region have to include?`,
                    r1_focus_label:         `How many sectors do you focus context-fit support on? (a sharp 2–3 beats trying to serve everything)`,
                    r1_focus_readout:       `Sectors in focus:`,
                    diagnosis_placefit:     `Its place-based assets — marine science, renewable-energy potential and agtech adjacent to sugar — are under-used; context-fit support there can build resilient enterprise`,
                    diagnosis_legacy:       `Double down on the legacy base — mining services, sugar and tourism are what the region knows; rebuild around them`,
                    diagnosis_copy:         `Nothing special — it’s a regional economy like any other; a proven accelerator model will work fine here`,
                    failure_context:        `It was a capital-city playbook dropped on a region with thin capital, distance to markets and different industries — it ignored what makes this place different`,
                    failure_underfunded:    `It was simply under-funded — the same model with more money would have worked`,
                    failure_founders:       `The founders here just aren’t good enough — the talent pool is the problem`,
                    inclusion_broad:        `Include Indigenous enterprise and the young, under-utilised talent pool the state weighs in its outcomes — place-based means socially inclusive, not just sector-smart`,
                    inclusion_established:  `Route everything through the established business community — they’re the safe, proven operators`,
                    inclusion_ignore:       `Inclusion is a nice-to-have — focus only on whatever moves the headline jobs number fastest`,

                    r2_alloc_label:         `Allocate the A$4.8M discretionary budget across the 10-venture pipeline — concentrate or spread?`,
                    r2_anchor_label:        `How do you handle the 600 disappearing jobs at the winding-down anchor employer?`,
                    r2_placefit_label:      `Within your allocation, how strongly do you weight place-fit (leveraging the region’s distinctive assets)?`,
                    r2_depth_label:         `Average funding depth per backed venture (A$ thousands) — too shallow and nothing scales`,
                    r2_depth_readout:       `Depth per backed venture:`,
                    r2_depth_hint:          `The last program spread A$1.5M thinly and produced 3 survivors. Thin grants across many ventures is exactly how starts become non-survivors. Concentration and real depth scale enterprises; spread distributes optics.`,
                    alloc_concentrate:      `Concentrate — back 3–4 high-place-fit, high-jobs ventures deeply enough to actually scale`,
                    alloc_hedge:            `Hedge — back 6 ventures at medium depth across stages, a bit of everything`,
                    alloc_spread:           `Spread thinly — a small grant to all 10 ventures so no one feels left out and it looks fair across every town`,
                    anchor_transition:      `Fund transition pathways that move those workers and suppliers into new place-fit ventures — build forward, don’t prop up a managed decline`,
                    anchor_prop:            `Pour support into the anchor contractor to save the 600 jobs — it’s the biggest jobs number on the table`,
                    anchor_ignore:          `Ignore it entirely — it’s leaving regardless, so put nothing toward those workers`,
                    placefit_strong:        `Weight it heavily — back the ventures that genuinely leverage marine science, renewables and agtech`,
                    placefit_some:          `Weight it somewhat — a tiebreaker among otherwise similar ventures`,
                    placefit_ignore:        `Don’t weight it — fund whoever applies first or shouts loudest`,

                    r3_program_label:       `Choose the development-program model — the “how” of support.`,
                    r3_partner_label:       `Prioritise ecosystem partners under limited funding — who do you invest co-funding and relationship in?`,
                    r3_indigenous_label:    `Do you fund a community-enterprise and Indigenous-business stream?`,
                    r3_coinvest_label:      `Co-investment commitment you secure from prioritised partners per A$1 of RCF (×)`,
                    program_sector:         `A place-fit blend — a sector incubator (marine/renewables), founder small-business skills, and a market-access/export track built for this region’s realities`,
                    program_accelerator:    `A generic 12-week startup accelerator — the proven capital-city model, run it again here`,
                    program_grants:         `Pure grant-giving — just write cheques and let ventures figure out the rest on their own`,
                    partner_leverage:       `Prioritise the two or three partners who actually bring co-investment and capability — the ones that move the leverage number`,
                    partner_even:           `Split partnership funding evenly across the university, the banks, three councils and four industry bodies — treat every partner equally`,
                    partner_goodwill:       `Prioritise the most visible, politically comfortable partners — the ones good for the photo`,
                    indigenous_yes:         `Yes — a genuine stream; the region’s growth assets include Indigenous enterprise and the state weighs inclusive outcomes`,
                    indigenous_token:       `A token line item — enough to mention in the report, not enough to deliver`,
                    indigenous_no:          `No — keep it simple and route support through the established business community only`,
                    coinvest_high:          `1.4x — firm co-investment from the partners that bring private capital and procurement linkage`,
                    coinvest_low:           `0.6x — a modest co-investment commitment from one willing partner`,
                    coinvest_none:          `0x — rely solely on the RCF grant, no private capital pulled in`,

                    r4_doubledown_label:    `12-month outcomes are back. What do you double down on, and what do you cut?`,
                    r4_pitch_label:         `Your pitch to the state funder (facilitator-played) for the contingent A$3.2M and the larger future allocation.`,
                    r4_additionality_label: `How do you answer the state’s additionality challenge — “would this have happened anyway?”`,
                    r4_conviction_label:    `Conviction: how firmly do you hold that place-fit concentration and co-investment beat a thin, imported spread? (%)`,
                    doubledown_winners:     `Double down on the place-fit ventures and partners that delivered jobs and leverage; cut what underperformed`,
                    doubledown_optics:      `Keep the thin spread going — cutting any town’s grant is politically painful, so fund everything again`,
                    doubledown_decline:     `Pour the renewal into the anchor employer’s wind-down to keep the headline jobs number alive a bit longer`,
                    pitch_outcomes:         `Lead with outcomes and additionality — ventures activated, jobs created, leverage toward 1.5x, and engagement, each caused by the intervention, not what would have happened anyway`,
                    pitch_grants:           `Lead with activity — how many grants we distributed and how fair the spread was across towns`,
                    pitch_spin:             `Spin the one metric that looks best and hope the state doesn’t ask about leverage or survival`,
                    additionality_own:      `Own it honestly — show which outcomes RCF genuinely caused, where co-investment proves market validation, and what we’d cut as low-additionality`,
                    additionality_dodge:    `Dodge it — claim every job and venture in the region as ours regardless of cause`,
                    additionality_deny:     `Deny it matters — outcomes are outcomes, the cause is the state’s problem not ours`,

                    warn_focus_range:       `Sectors in focus must be between 1 and 6.`,
                    warn_depth_range:       `Funding depth must be between A$80k and A$600k per venture.`,
                    warn_coinvest_value:    `The co-investment commitment cannot be negative.`,
                    warn_conviction_range:  `Conviction must be a percentage between 0 and 100.`,

                    coach_default:          `Decision logged.`,
                    coach_r1_placefit:      `<strong>That is reading the place.</strong> Marine science, renewables and an agtech adjacency to sugar are assets nobody is using — and context-fit support there can build enterprise that survives the next commodity cycle. Now design support <em>for that</em>, not for a generic startup scene.`,
                    coach_r1_legacy:        `<strong>Rebuilding around mining services, sugar and tourism is rebuilding on the exposure that got you here.</strong> Those legacy sectors are exactly the commodity- and climate-cycle risk the region keeps falling through. Where is the forward asset — the marine science, the renewables — that a place-based read would surface?`,
                    coach_r1_copy:          `<strong>“It’s a regional economy like any other” is precisely Barrett’s warning.</strong> Entrepreneurship is context-dependent — what works in a capital city need not work here, with thin capital and distance to markets. A proven model from somewhere else is how you produce 3 survivors from A$1.5M again.`,
                    coach_r1_underfunded:   `<strong>“The same model with more money” misreads the failure.</strong> The accelerator didn’t fail for lack of cash; it failed because it was a metropolitan playbook in a region it didn’t fit. Pouring more into the wrong model just produces a more expensive failure.`,
                    coach_r1_founders:      `<strong>Blaming the founders is the easy out — and the wrong one.</strong> The region has the highest formation rate in regional Queensland; people start ventures. They don’t <em>scale</em> because the support ignores thin capital, distance and the assets that actually fit here. Fix the design, not the people.`,
                    coach_r1_established:   `<strong>Routing everything through the established business community leaves growth assets on the table.</strong> The region’s talent base includes Indigenous enterprise and a young, under-utilised workforce — and the state weighs inclusive outcomes. Whose ventures are you systematically leaving out?`,
                    coach_r1_ignoreincl:    `<strong>Treating inclusion as optional costs you twice.</strong> You lose the impact of an under-utilised talent pool <em>and</em> the funding weighting the state places on inclusive outcomes. Place-based means socially inclusive, not just sector-smart.`,
                    coach_r1_sharp:         `<strong>Sharp place-based diagnosis.</strong> You named the distinctive assets, read the accelerator failure as a context problem not a money problem, and included the talent the established community overlooks. That is the foundation everything else is built on.`,
                    coach_r2_concentrate:   `<strong>Concentration is the discipline the last program lacked.</strong> Backing a few high-place-fit, high-jobs ventures deeply is how starts become survivors. It carries the political risk of “picking winners” — but the state measures jobs and ventures activated, not grants distributed.`,
                    coach_r2_hedge:         `<strong>Hedging across six is better than spraying all ten, but it is still diluted.</strong> A bit of everything rarely funds anything deeply enough to scale. The ventures that hit the 12-month target are the ones backed to real depth — where is your sharpest bet?`,
                    coach_r2_spread:        `<strong>A small grant to all ten so no one feels left out — that is exactly how the last program failed.</strong> Many starts, almost no survivors. The state counts jobs created and ventures activated, not the fairness of the spread. Thin spread is optics; it will not hit the target.`,
                    coach_r2_prop:          `<strong>Pouring support into the wind-down contractor funds a managed decline.</strong> Those 600 jobs are leaving the region regardless — you are cushioning an exit, not building new enterprise. Those workers need <em>new</em> ventures to move into. Where is the forward bet?`,
                    coach_r2_ignoreanchor:  `<strong>Ignoring the anchor workers entirely is a different miss.</strong> You are right not to prop up the decline — but the suppliers and skilled workers around it are exactly the talent your new ventures could absorb. Build transition pathways, don’t just walk away.`,
                    coach_r2_placefit:      `<strong>Concentration plus heavy place-fit weighting is the strongest allocation.</strong> Backing the marine, renewables and agtech ventures deeply is support designed for this region’s assets — and those are the enterprises most likely to survive and to attract co-investment.`,
                    coach_r3_accelerator:   `<strong>You re-ran the 12-week accelerator — the exact model that produced 3 survivors from A$1.5M here.</strong> A capital-city playbook in a region with thin capital, 600 jobs disappearing, and marine and renewables assets nobody is using. What about <em>this place</em> is that program actually built for?`,
                    coach_r3_grants:        `<strong>Pure grant-giving is RCF abdicating its real job.</strong> The mandate is ecosystem orchestration, not a cheque-writing window. Cheques without an incubator, founder skills or market access leave founders to scale alone — in a region where scaling is precisely what fails.`,
                    coach_r3_leverage:      `<strong>That is strategic partner prioritisation.</strong> The two or three partners who actually bring co-investment and procurement linkage are the ones that move leverage off 0.4x. Partners are sources of capital and capability, not trophies — you have funded the ones that move the number.`,
                    coach_r3_even:          `<strong>Splitting partnership funding evenly treats partners as trophies.</strong> The university, the banks, three councils and four industry bodies do not bring equal co-investment — and your leverage is stuck at 0.4x against a 1.5x target. Which two actually move the number, and which are just on the photo?`,
                    coach_r3_goodwill:      `<strong>Prioritising the photogenic partners is the same trap dressed up.</strong> Visibility is not co-investment. The partners good for the announcement are rarely the ones writing a private cheque — and leverage is the financial spine of your case to the state.`,
                    coach_r3_noindigenous:  `<strong>No community-enterprise or Indigenous stream leaves real growth assets unfunded.</strong> The region’s assets include Indigenous enterprise, and the state explicitly weighs inclusive outcomes. Excluding them costs you both impact and funding — place-based means inclusive.`,
                    coach_r3_nocoinvest:    `<strong>Relying solely on the RCF grant is how leverage stays at 0.4x.</strong> When 40% of next year’s grant is contingent and you have leveraged nothing, the budget shrinks and the ventures collapse with it. How does each dollar you spend pull a private dollar in behind it?`,
                    coach_r4_winners:       `<strong>Doubling down on what delivered is outcome discipline.</strong> Cutting the underperformers and concentrating the renewal on the place-fit ventures and co-investing partners is exactly the additionality logic the state rewards — you are funding what works, not what is comfortable.`,
                    coach_r4_optics:        `<strong>Funding everything again to avoid cutting any town keeps the thin-spread trap running.</strong> It is politically comfortable and it is why the region keeps producing starts without survivors. The renewal should follow the outcomes, not the optics.`,
                    coach_r4_decline:       `<strong>Pouring the renewal into the wind-down keeps a headline number alive and builds nothing.</strong> The anchor is leaving — money spent there is a rear-guard action. The state is comparing you to a rival region on <em>new</em> enterprise, not on cushioning an exit.`,
                    coach_r4_outcomes:      `<strong>That is the case the state will renew.</strong> Ventures activated, jobs created, leverage moving toward 1.5x and engagement — each genuinely caused by the intervention. Outcome-based funding rewards measured results and additionality, and you have brought both.`,
                    coach_r4_grants:        `<strong>Leading with how many grants you distributed answers a question the state did not ask.</strong> They measure jobs created and ventures activated, not grants handed out or the fairness of the spread. Activity is not outcome — and the rival region is pitching outcomes.`,
                    coach_r4_spin:          `<strong>Spinning the one metric that looks best is how a funder stops trusting you.</strong> The state can see leverage and survival. Highlight the favourable number and dodge the rest, and they will assume the rest is worse than it is — and hand the larger allocation to the rival.`,
                    coach_r4_dodge:         `<strong>Claiming every job in the region as yours fails the additionality test.</strong> Outcomes-based funders ask whether it would have happened anyway. Overclaim and you lose credibility on the numbers you genuinely earned. Show what RCF actually caused.`,
                    coach_r4_deny:          `<strong>“The cause is the state’s problem” misunderstands outcomes-based funding.</strong> Additionality is the whole point — the state is buying caused outcomes, not coincidental ones. Deny it matters and you concede the argument the rival region is making against you.`,

                    sum_default:            `Decision made.`,
                    sum_r1_good:            `Read the place; failure as context not money; included the overlooked talent.`,
                    sum_r1_weak:            `Mis-read the place or treated it like any other region.`,
                    sum_r2_good:            `Concentrated on place-fit ventures; funded transition, not decline.`,
                    sum_r2_spread:          `Spread the budget thinly across all ten — the accelerator trap.`,
                    sum_r2_decline:         `Propped up the departing anchor — funded a managed decline.`,
                    sum_r2_weak:            `Allocation under-tuned for depth or place-fit.`,
                    sum_r3_good:            `Place-fit program; leverage-bringing partners; firm co-investment.`,
                    sum_r3_imported:        `Re-ran the generic accelerator — the imported playbook.`,
                    sum_r3_trophy:          `Treated partners as trophies — leverage left on the table.`,
                    sum_r3_weak:            `Program or partners partially fitted.`,
                    sum_r4_good:            `Doubled down on what worked; led with outcomes; owned additionality.`,
                    sum_r4_weak:            `Defended optics, propped decline, or dodged additionality.`,

                    insight_placebased:     `Place-based recovery: you read the region before designing anything, concentrated funding on high-place-fit ventures, chose a program built for this place, and prioritised the partners that brought real co-investment. Leverage moved toward 1.5x, ventures activated and jobs landed — the case that secures the contingent A$3.2M and the larger allocation.`,
                    insight_imported:       `Imported playbook: you ran a generic metropolitan model in a region it does not fit — exactly the pattern that produced 3 survivors from A$1.5M. Entrepreneurship is context-dependent; the program never matched the place, so ventures activated and survival stayed capped.`,
                    insight_spread:         `Thin-spread trap: you divided the budget to look fair across every applicant and town, producing many starts and few survivors — the accelerator failure repeated. The state measures jobs created and ventures activated, not grants distributed, and the spread hit neither target.`,
                    insight_decline:        `Managed decline: you poured support into the departing anchor employer instead of building new enterprise. Those jobs were leaving regardless — you cushioned an exit rather than creating resilient capacity, and the activated-ventures number never recovered.`,
                    insight_trophy:         `Trophy partners: you treated every ecosystem partner as equally worth funding, so the few that actually bring co-investment were diluted. Leverage stayed stuck near 0.4x against a 1.5x target — and leverage is the financial spine the state’s renewal rests on.`,
                    insight_inclusion:      `Inclusion neglected: you routed support through the established business community and left Indigenous enterprise and the under-utilised talent pool unfunded. Place-based means socially inclusive — you lost both the impact and the funding the state weights toward inclusive outcomes.`,
                    insight_mixed:          `A mixed result: some place-based discipline landed, but the allocation, program and partner choices did not fully reinforce one another — enough gaps for the state to question whether the outcomes are genuinely caused and the recovery durable.`,
                    insight_leverage_low:   `Funding leverage never reached 1.5x: with the grant contingent and little private capital pulled in, the budget shrinks and the ventures shrink with it. Partner prioritisation and co-investment are the lever — leaving leverage low forfeits the sustainability case.`,
                    insight_decline_cost:   `Funding the decline cost you forward capacity: money spent cushioning the anchor’s exit is money not spent building the new ventures the region needs — a rear-guard action when the state is comparing you to a rival on new enterprise.`,
                    insight_inclusion_cost: `Neglecting inclusion cost twice: the impact of an under-utilised talent base and the funding weighting the state places on inclusive outcomes both went unrealised.`,
                    insight_survival_low:   `Venture survival stayed below the 55% benchmark with too few ventures activated: shallow or scattered support produced starts, not survivors — the region’s chronic pattern, unbroken.`,
                    insight_caused:         `Crucially, the outcomes are <em>additional</em>: co-investment proves market validation, and the activated ventures and jobs were genuinely caused by the intervention — the additionality story that wins outcome-based renewal.`,

                    hint_spread:            `You spread the budget thinly — ventures and survival are now capped, the accelerator failure repeating. Concentrate the remaining decisions on a few high-place-fit ventures backed to real depth.`,
                    hint_imported:          `You imported a generic model that does not fit the place — ventures activated and survival are capped. Pivot to place-fit program design and back the assets this region actually has.`,
                    hint_decline:           `You funded the departing anchor’s decline — those jobs are temporary and new ventures are capped. Redirect toward transition into new place-fit enterprise.`,
                    hint_trophy:            `You treated partners as trophies — leverage is stuck near 0.4x. Prioritise the two or three partners that bring real co-investment and secure a firm commitment.`,
                    hint_leverage:          `Funding leverage is far below the 1.5x target. Partner prioritisation and co-investment are the lever — without it, the contingent A$3.2M is forfeit.`,
                    hint_strong:            `Strong place-based position — ventures, leverage and engagement are all healthy. Land it: double down on what worked and lead the state with outcomes and additionality.`,

